use gluesql_core::error::Result;
use gluesql_redis_storage::RedisStorage;

fn count_rows(storage: &RedisStorage, table_name: &str) -> Result<usize> {
    // Construct the key for the table's row count
    let count_key = format!("{}_count", table_name);

    // Retrieve the count from Redis
    match storage.get(count_key.as_str()) {
        Ok(Some(count_str)) => {
            if let Ok(count) = count_str.parse::<usize>() {
                Ok(count)
            } else {
                Err("Failed to parse count value".into())
            }
        }
        Ok(None) => {
            // If count doesn't exist, return 0
            Ok(0)
        }
        Err(e) => Err(e),
    }
}

fn increment_counter(
    kv: &Kv,
    key: Vec<AnyValue>,
) -> Result<(), KvError> {
    let mut batch = kv.batch()?;
    batch.sum(key, 1)?;
    batch.commit()?;
    Ok(())
}

