fn list_active_gateways(&self, dbtx: &mut DatabaseTransaction<'_>) -> Vec<(PublicKey, u64)> {
    let mut gateways = Vec::new();
    let prefix = LightningGatewayKeyPrefix::current();
    let keys = dbtx.get_prefix(prefix);

    for key in keys {
        let gateway_key: LightningGatewayKey = key;
        let expiration_time = gateway_key.expiration_time;
        if expiration_time > self.time().now() {
            gateways.push((gateway_key.public_key, expiration_time));
        }
    }

    gateways
}

