fn dial_with_fallback<T: Provider>(
    transport: &mut Transport<T>,
    addr: Multiaddr,
) -> Result<T::Stream, io::Error> {
    let mut opts = DialOpts::new();
    opts.port_use = PortUse::Reuse;
    opts.endpoint = Endpoint::Dial;

    let result = transport.dial_addr(&addr, &opts);
    if let Err(e) = &result {
        if e.raw_os_error() == Some(libc::EADDRNOTAVAIL) {
            opts.port_use = PortUse::New;
            return transport.dial_addr(&addr, &opts);
        }
    }

    result
}

