fn list_large_files(&self, min_size: u64) -> Result<Vec<ObjectId>, FileCenterError> {
    let filter = doc! { "size": { "$gt": min_size } };
    let mut ids = Vec::new();

    self.collections.files
        .find(filter, None)
        .try_for_each(|doc| {
            if let Ok(id) = doc.get_object_id("id") {
                ids.push(id.clone());
            }
            Ok(())
        })
        .await?;

    Ok(ids)
}

