use std::io::Result;
use crossterm_winapi::{ScreenBuffer, Console, InputRecord};

fn poll_key(screen_buffer: &ScreenBuffer) -> Result<Option<char>> {
    let console = Console::from_screen_buffer(screen_buffer)?;
    let input_records = console.poll_input()?;

    if input_records.is_empty() {
        return Ok(None);
    }

    let input_record = input_records[0];
    let mut key_event = input_record.key_event();

    if key_event.virtual_key_code.is_none() {
        return Ok(None);
    }

    let char_code = key_event.character.UnicodeChar;
    Ok(Some(char_code as char))
}

