use anyhow::Result;

fn calculate_mint_audit_totals(
    dbtx: &mut DatabaseTransaction<'_>
) -> Result<(Amount, Amount)> {
    let issued_total = Amount::ZERO;
    let redeemed_total = Amount::ZERO;

    // Iterate over all audit items with the "issued" prefix
    for item in dbtx.iter_prefix(MintAuditItemKeyPrefix::Issued) {
        if let Some(key) = item.key {
            if let Some(value) = item.value {
                if let Ok(amount) = Amount::from_bytes(value) {
                    issued_total += amount;
                }
            }
        }
    }

    // Iterate over all audit items with the "redeemed" prefix
    for item in dbtx.iter_prefix(MintAuditItemKeyPrefix::Redeemed) {
        if let Some(key) = item.key {
            if let Some(value) = item.value {
                if let Ok(amount) = Amount::from_bytes(value) {
                    redeemed_total += amount;
                }
            }
        }
    }

    Ok((issued_total, redeemed_total))
}

use std::env;
use crate::OsError;

fn get_env_or_default(key: &str, default: &str) -> Result<String, OsError> {
    // Validate the key
    if key.is_empty() {
        return Err(OsError::InvalidKey);
    }
    if key.contains('\0') {
        return Err(OsError::InvalidKey);
    }

    // Get the environment variable
    let value = env::var(key).unwrap_or_default();

    // If the value is empty, use the default
    if value.is_empty() {
        env::set_var(key, default);
        return Ok(default.to_string());
    }

    Ok(value)
}

fn update_audit_entry(&self, dbtx: &mut DatabaseTransaction<'_>, contract_id: ContractId) {
    let contract = self.get_contract(dbtx, &contract_id).expect("Contract not found");
    let amount = contract.amount;

    if amount == 0 {
        // Remove the audit entry if the contract amount is zero
        dbtx.delete(&LightningAuditItemKey::from(contract_id));
    } else {
        // Update the audit entry with the remaining amount
        let contract_key = ContractKey::from(contract_id);
        dbtx.put(
            &contract_key,
            &serde_json::to_vec(&contract).expect("Failed to serialize contract"),
        );
    }
}

