fn generate_and_save_key_pair(path: &Path) -> io::Result<()> {
    // Generate a new ED25519 key pair
    let key_pair = SecretKey::ed25519();

    // Create a KeyFile instance with the generated key pair
    let key_file = KeyFile::new(
        KeyType::Ed25519,
        key_pair.public_key(),
        key_pair.secret_key(),
        AccountId::new_unchecked("test.account.near"),
    );

    // Write the key file to the specified path
    std::fs::write(path, serde_json::to_string(&key_file).unwrap())?;

    Ok(())
}

