fn write_struct_array(
    path: &std::path::Path,
    array: vortex::arrays::StructArray,
    batch_size: usize,
    object_store: std::sync::Arc<dyn object_store::ObjectStore>,
) -> vortex::error::VortexResult<()> {
    let dtype = array.dtype();
    let num_rows = array.len();
    let mut offset = 0;

    while offset < num_rows {
        let end = std::cmp::min(offset + batch_size, num_rows);
        let batch = array.slice(offset..end);
        let stream = ArrayStreamAdapter::new(batch);
        let options = VortexWriteOptions::new()
            .with_path(path)
            .with_object_store(object_store.clone())
            .with_dtype(dtype.clone())
            .with_compression(vortex::compression::Compression::Zstd);
        vortex::file::write_stream(stream, options)?;
        offset = end;
    }

    Ok(())
}

fn scan_range_with_cursor(
    kv: &Kv,
    prefix: Vec<deno_kv::interface::AnyValue>,
    limit: u32,
) -> Result<Vec<deno_kv::interface::KvEntry<unknown>>, KvError> {
    let mut entries = Vec::new();
    let mut cursor = Vec::new();

    loop {
        let selector = RawSelector::new(prefix.clone(), None);
        let options = KvListOptions::new().with_limit(limit).with_cursor(cursor);
        let list_result = kv.list(selector, options)?;

        entries.extend(list_result.entries);

        if list_result.cursor.is_empty() {
            break;
        }

        cursor = list_result.cursor;
    }

    Ok(entries)
}
